import{_ as t,o as r,c as a,ae as e}from"./chunks/framework.Dzr56EFm.js";const d=JSON.parse('{"title":"产品发布 - 2026-07-05","description":"","frontmatter":{"date":"2026-07-05T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-07-05-product.md","filePath":"daily/2026-07-05-product.md"}'),n={name:"daily/2026-07-05-product.md"};function s(i,o,p,l,g,h){return r(),a("div",null,[...o[0]||(o[0]=[e('<h1 id="产品发布-2026-07-05" tabindex="-1">产品发布 - 2026-07-05 <a class="header-anchor" href="#产品发布-2026-07-05" aria-label="Permalink to &quot;产品发布 - 2026-07-05&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日产品发布领域动态汇总：Notion计划推出多项非AI新特性以提升用户体验；数字.ai发布23.3版本，引入自助工作流简化部署；Product Copilot作为AI助手集成于Jira和Confluence中，提高产品管理效率；Notion AI新增16项功能，旨在提升工作效率；微软Copilot作为面向组织的AI工具，提供基于聊天的生成式AI交互。最值得关注的是微软Copilot的发布，它可能改变组织和业务的工作方式。</p><hr><h3 id="_1-今年notion将推出哪些非ai新特性" tabindex="-1">1. 今年Notion将推出哪些非AI新特性？ <a class="header-anchor" href="#_1-今年notion将推出哪些非ai新特性" aria-label="Permalink to &quot;1. 今年Notion将推出哪些非AI新特性？&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.reddit.com/r/Notion/comments/1qbod39/what_new_features_will_come_to_notion_this_year" target="_blank" rel="noreferrer">What new features will come to Notion this year that are not AI-based?</a></p><p><strong>一句话摘要</strong>: Notion今年将推出多项非AI新特性，提升用户体验。</p><p><strong>能解决什么问题</strong>: 解决用户在数据关联、文件导出、团队协作等方面的需求。</p><p><strong>产品应用</strong>: 这些特性可以直接应用于Notion产品中，提高工作效率和协作便利性。</p><p><strong>示例场景</strong>: 团队成员可以在Notion中实时讨论数据库内容。</p><hr><h3 id="_2-数字-ai发布23-3版本工作流概览" tabindex="-1">2. 数字.ai发布23.3版本工作流概览 <a class="header-anchor" href="#_2-数字-ai发布23-3版本工作流概览" aria-label="Permalink to &quot;2. 数字.ai发布23.3版本工作流概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://docs.digital.ai/release/docs/how-to/workflows-overview" target="_blank" rel="noreferrer">Workflows Overview · digital.ai Release</a></p><p><strong>一句话摘要</strong>: 数字.ai发布23.3引入自助工作流简化开发者应用部署。</p><p><strong>能解决什么问题</strong>: 解决开发者在部署应用时对工具知识要求高和环境设置复杂的问题。</p><p><strong>产品应用</strong>: 适用于需要简化云应用部署流程和提高性能可靠性的产品。</p><p><strong>示例场景</strong>: 开发者使用工作流快速部署云应用并确保安全合规。</p><hr><h3 id="_3-产品副驾驶——软件产品团队的ai助手" tabindex="-1">3. 产品副驾驶——软件产品团队的AI助手 <a class="header-anchor" href="#_3-产品副驾驶——软件产品团队的ai助手" aria-label="Permalink to &quot;3. 产品副驾驶——软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: Product Copilot是集成在Jira和Confluence中的AI助手，提升产品管理效率。</p><p><strong>能解决什么问题</strong>: 解决产品团队在用户故事一致性、协作和产品开发速度上的挑战。</p><p><strong>产品应用</strong>: 适用于任何希望优化其待办事项管理的产品负责人，无需切换工具即可使用。</p><p><strong>示例场景</strong>: 产品负责人使用Product Copilot在Jira中创建清晰的任务票。</p><hr><h3 id="_4-16项notion新功能更新概览-16分钟" tabindex="-1">4. 16项Notion新功能更新概览（16分钟） <a class="header-anchor" href="#_4-16项notion新功能更新概览-16分钟" aria-label="Permalink to &quot;4. 16项Notion新功能更新概览（16分钟）&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=GnonRPjbzZY" target="_blank" rel="noreferrer">16 New Notion Updates (in just 16 minutes) - YouTube</a></p><p><strong>一句话摘要</strong>: Notion AI新增16项功能，提升工作效率。</p><p><strong>能解决什么问题</strong>: 解决团队协作中信息整合、历史追踪和自动化记录的问题。</p><p><strong>产品应用</strong>: 适用于需要高效协作和信息管理的团队，通过Notion AI实现自动化和信息检索。</p><p><strong>示例场景</strong>: 团队成员通过Notion AI追踪项目变更历史。</p><hr><h3 id="_5-微软copilot-面向组织的ai工具" tabindex="-1">5. 微软Copilot | 面向组织的AI工具 <a class="header-anchor" href="#_5-微软copilot-面向组织的ai工具" aria-label="Permalink to &quot;5. 微软Copilot | 面向组织的AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/organizations" target="_blank" rel="noreferrer">Microsoft Copilot | AI Tools for Organizations</a></p><p><strong>一句话摘要</strong>: 微软Copilot提供基于聊天的生成式AI交互，助力组织和业务。</p><p><strong>能解决什么问题</strong>: 提升工作效率，增强安全防护，优化代码编写。</p><p><strong>产品应用</strong>: 可应用于企业日常运营、安全IT、编程等多个领域。</p><p><strong>示例场景</strong>: 使用Microsoft 365 Copilot提高文档处理效率。</p><hr><h3 id="_6-亚马逊推出针对办公室工作人员的ai生产力软件" tabindex="-1">6. 亚马逊推出针对办公室工作人员的AI生产力软件 <a class="header-anchor" href="#_6-亚马逊推出针对办公室工作人员的ai生产力软件" aria-label="Permalink to &quot;6. 亚马逊推出针对办公室工作人员的AI生产力软件&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.bloomberg.com/news/articles/2026-04-28/amazon-launches-ai-productivity-software-for-office-workers" target="_blank" rel="noreferrer">Amazon (AMZN) Launches AI Productivity Software for Office Workers - Bloomberg</a></p><p><strong>一句话摘要</strong>: 亚马逊云服务部门推出AI驱动的办公生产力软件</p><p><strong>能解决什么问题</strong>: 提高物流人员和招聘人员的工作效率</p><p><strong>产品应用</strong>: 可以应用到企业中，通过AI技术优化决策和招聘流程</p><p><strong>示例场景</strong>: 物流公司使用AI软件优化货物分配</p><hr><h3 id="_7-微软copilot" tabindex="-1">7. 微软Copilot <a class="header-anchor" href="#_7-微软copilot" aria-label="Permalink to &quot;7. 微软Copilot&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://en.wikipedia.org/wiki/Microsoft_Copilot" target="_blank" rel="noreferrer">Microsoft Copilot</a></p><p><strong>一句话摘要</strong>: 微软基于大型语言模型开发的AI聊天机器人</p><p><strong>能解决什么问题</strong>: 替代已停用的Cortana，提供智能助手服务</p><p><strong>产品应用</strong>: 可用于Bing、Edge、Windows和Microsoft 365，实现个性化AI助手</p><p><strong>示例场景</strong>: 使用Copilot Studio创建自定义AI助手</p><hr><h3 id="_8-ai新闻-导致市场崩溃的ai产品发布" tabindex="-1">8. AI新闻：导致市场崩溃的AI产品发布 <a class="header-anchor" href="#_8-ai新闻-导致市场崩溃的ai产品发布" aria-label="Permalink to &quot;8. AI新闻：导致市场崩溃的AI产品发布&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=xdp8bulnidY&amp;vl=en-US" target="_blank" rel="noreferrer">AI News: The AI Launch That Crashed The Market - YouTube</a></p><p><strong>一句话摘要</strong>: 本周AI领域发生了许多重大新闻。</p><p><strong>能解决什么问题</strong>: 提供AI编程辅助、模型更新和视频工具优化。</p><p><strong>产品应用</strong>: 可以应用到软件开发、视频制作等领域，提高效率。</p><p><strong>示例场景</strong>: 使用Codex app辅助编写代码。</p><hr><h3 id="_9-notion-3-4版本新特性概览" tabindex="-1">9. Notion 3.4版本新特性概览 <a class="header-anchor" href="#_9-notion-3-4版本新特性概览" aria-label="Permalink to &quot;9. Notion 3.4版本新特性概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=Z5hwjq5K0eY" target="_blank" rel="noreferrer">What&#39;s New in Notion 3.4</a></p><p><strong>一句话摘要</strong>: Notion 3.4引入了仪表板、新侧边栏、演示模式等多项功能。</p><p><strong>能解决什么问题</strong>: 提高团队协作效率，优化信息管理和展示。</p><p><strong>产品应用</strong>: 适用于需要高效信息管理和团队协作的企业和团队。</p><p><strong>示例场景</strong>: 企业使用Notion仪表板监控关键业务指标。</p><hr><h3 id="_10-figma-ai工具向所有用户推出的发布日期" tabindex="-1">10. Figma AI工具向所有用户推出的发布日期 <a class="header-anchor" href="#_10-figma-ai工具向所有用户推出的发布日期" aria-label="Permalink to &quot;10. Figma AI工具向所有用户推出的发布日期&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://forum.figma.com/ask-the-community-7/release-date-for-ai-tool-rollout-to-all-users-26131" target="_blank" rel="noreferrer">Release Date for AI Tool Rollout to All Users? | Figma Forum</a></p><p><strong>一句话摘要</strong>: Figma AI工具仍在有限测试阶段，全面发布日期未定</p><p><strong>能解决什么问题</strong>: 解决设计工作中的自动化和效率问题</p><p><strong>产品应用</strong>: 可应用于产品设计，通过AI辅助提高设计效率和质量</p><p><strong>示例场景</strong>: 设计师使用Figma AI自动生成UI元素</p><hr>',75)])])}const u=t(n,[["render",s]]);export{d as __pageData,u as default};
